     1	import Foundation
     2	
     3	/// Switch Angle (road map "creator-jobs" SW1, spec §11 SW-13…SW-15): which
     4	/// tracks are angles for a shot, and the sequence that re-picks the shot from
     5	/// one. Clip ▸ Switch Angle ▸ (`EditorViewController+SwitchAngle.swift`) and
     6	/// `switch_angle` (`AgentServer+Switch.swift`) both run it. It names no
     7	/// `rc_*`: every op is tried through `ReelProject.applying(_:)`.
     8	///
     9	/// **Covering (SW-13, SW-15 (d)).** A track covers a span when its media
    10	/// clips with a picture (`sourceSize(of:) != nil`) leave no tick of it
    11	/// uncovered; a clip with its picture switched off, or on a hidden track,
    12	/// still counts.
    13	///
    14	/// **The re-pick (SW-14, SW-15 (e)).** With B the shot between A and C on its
    15	/// track: `delete` B, trim A's end to B's start and C's start to B's end
    16	/// (each `alone`), one `copy_pieces` per angle clip the span crosses (B's
    17	/// switches), then A and C trimmed back to their old edges and the two
    18	/// transitions put back. The ops are tried one at a time on the container's
    19	/// handle, because `applying([ReelOp])` does not stop at a refusal: a refusal
    20	/// before the trim-backs, or a trim away held short of its target, refuses
    21	/// the whole plan and nothing is committed; a trim-back that is refused or
    22	/// held short is left out with its edge's transition, and the step is named
    23	/// "Switch Angle (transition removed)".
    24	enum SwitchAngle {
    25	    /// One row of Clip ▸ Switch Angle ▸.
    26	    struct Angle: Equatable {
    27	        let track: UInt32
    28	        let title: String
    29	    }
    30	
    31	    /// The most rows the submenu lists.
    32	    static let menuLimit = 9
    33	    static let actionName = "Switch Angle"
    34	    static let removedName = "Switch Angle (transition removed)"
    35	
    36	    /// The ops of a re-pick, its step's name, the new pieces' ids in time
    37	    /// order, and how many of the shot's two transitions were dropped.
    38	    struct Plan {
    39	        let ops: [ReelOp]
    40	        let actionName: String
    41	        let pieces: [UInt32]
    42	        let transitionsRemoved: Int
    43	    }
    44	
    45	    enum Answer {
    46	        case plan(Plan)
    47	        case refused(String)
    48	    }
    49	
    50	    /// The media clips with a picture on `track`, by start.
    51	    static func pictureClips(on track: UInt32, in snapshot: ProjectSnapshot) -> [ClipSnapshot] {
    52	        snapshot.clips(onTrack: track).filter { clip in
    53	            guard case .media = clip.source else { return false }
    54	            return snapshot.sourceSize(of: clip) != nil
    55	        }
    56	    }
    57	
    58	    /// The first tick of `[from, to)` no picture clip on `track` covers, or
    59	    /// nil when the track covers the whole span.
    60	    static func firstUncovered(
    61	        track: UInt32, from: Ticks, to: Ticks, in snapshot: ProjectSnapshot
    62	    ) -> Ticks? {
    63	        var reached = from
    64	        for clip in pictureClips(on: track, in: snapshot) where clip.end > reached {
    65	            if clip.start > reached { return reached }
    66	            reached = clip.end
    67	            if reached >= to { return nil }
    68	        }
    69	        return reached < to ? reached : nil
    70	    }
    71	
    72	    /// Every other track of the container covering `clip`'s whole span, front
    73	    /// first, at most `menuLimit`. A name two listed tracks share gets " (n)",
    74	    /// n the track's 1-based position from the back.
    75	    static func angles(for clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> [Angle] {
    76	        let covering = snapshot.tracks.reversed()
    77	            .filter {
    78	                $0.id != clip.track
    79	                    && firstUncovered(track: $0.id, from: clip.start, to: clip.end, in: snapshot)
    80	                        == nil
    81	            }
    82	            .prefix(menuLimit)
    83	        let names = covering.map(\.name)
    84	        return covering.map { track in
    85	            guard names.filter({ $0 == track.name }).count > 1 else {
    86	                return Angle(track: track.id, title: track.name)
    87	            }
    88	            let position = (snapshot.trackIndex(of: track.id) ?? 0) + 1
    89	            return Angle(track: track.id, title: "\(track.name) (\(position))")
    90	        }
    91	    }
    92	
    93	    /// Re-picks clip `id` from track `angle` in `container` (the handle of
    94	    /// the container being edited). Throws for an unknown clip or track.
    95	    static func plan(clip id: UInt32, angle: UInt32, in container: ReelProject) throws -> Answer {
    96	        let snapshot = container.snapshot
    97	        guard let shot = snapshot.clip(id) else {
    98	            throw ReelCoreError(message: "no clip with id \(id)")
    99	        }
   100	        guard snapshot.track(angle) != nil else {
   101	            throw ReelCoreError(message: "no track with id \(angle)")
   102	        }
   103	        if let why = refusal(shot, angle: angle, in: snapshot) { return .refused(why) }
   104	
   105	        let (s, e) = (shot.start, shot.end)
   106	        let neighbours = snapshot.clips(onTrack: shot.track).filter { $0.id != shot.id }
   107	        let before = neighbours.last { $0.start < s && $0.end > s }
   108	        let after = neighbours.first { $0.start > s && $0.start < e }
   109	        var trial = Trial(project: container)
   110	
   111	        if let why = try trial.require(.delete(clips: [id])) { return .refused(why) }
   112	        if let a = before {
   113	            if let why = try trial.require(.trimEnd(clip: a.id, to: s, alone: true)) {
   114	                return .refused(why)
   115	            }
   116	            let reached = trial.project.snapshot.clip(a.id)?.end ?? a.end
   117	            if reached != s { return .refused(held(a.id, reached, s, shot: id)) }
   118	        }
   119	        if let c = after {
   120	            if let why = try trial.require(.trimStart(clip: c.id, to: e, alone: true)) {
   121	                return .refused(why)
   122	            }
   123	            let reached = trial.project.snapshot.clip(c.id)?.start ?? c.start
   124	            if reached != e { return .refused(held(c.id, reached, e, shot: id)) }
   125	        }
   126	        for range in pieceRanges(angle: angle, from: s, to: e, in: snapshot) {
   127	            let op = ReelOp.copyPieces(
   128	                clip: range.clip, track: shot.track, ranges: [(range.from, range.to)],
   129	                video: shot.enabled.video, audio: shot.enabled.audio)
   130	            if let why = try trial.require(op) { return .refused(why) }
   131	        }
   132	        let known = Set(snapshot.clips.map(\.id))
   133	        let pieces = trial.project.snapshot.clips(onTrack: shot.track)
   134	            .filter { !known.contains($0.id) }.map(\.id)
   135	
   136	        var removed = 0
   137	        if let a = before, let first = pieces.first {
   138	            let back = ReelOp.trimEnd(clip: a.id, to: a.end, alone: true)
   139	            if try trial.attempt(back, holds: { $0.clip(a.id)?.end == a.end }) {
   140	                try trial.putBack(shot.transitionIn, on: first)
   141	            } else {
   142	                removed += 1
   143	                try trial.clearTransition(on: first)
   144	            }
   145	        }
   146	        if let c = after, !pieces.isEmpty {
   147	            let back = ReelOp.trimStart(clip: c.id, to: c.start, alone: true)
   148	            if try trial.attempt(back, holds: { $0.clip(c.id)?.start == c.start }) {
   149	                try trial.putBack(c.transitionIn, on: c.id)
   150	            } else {
   151	                removed += 1
   152	                try trial.clearTransition(on: c.id)
   153	            }
   154	        }
   155	        return .plan(
   156	            Plan(
   157	                ops: trial.ops, actionName: removed > 0 ? removedName : actionName,
   158	                pieces: pieces, transitionsRemoved: removed))
   159	    }
   160	
   161	    /// SW-15 (c)'s refusals, in order.
   162	    private static func refusal(
   163	        _ shot: ClipSnapshot, angle: UInt32, in snapshot: ProjectSnapshot
   164	    ) -> String? {
   165	        if angle == shot.track {
   166	            return "track \(angle) is clip \(shot.id)'s own track; an angle is another track"
   167	        }
   168	        if snapshot.track(shot.track)?.locked == true {
   169	            return "track \(shot.track) is locked, so clip \(shot.id) cannot be re-picked"
   170	        }
   171	        if let partner = shot.linked {
   172	            return "clip \(shot.id) is linked to clip \(partner) (Detach Audio's pair); "
   173	                + "Switch Angle re-picks a clip with no link"
   174	        }
   175	        if let tick = firstUncovered(track: angle, from: shot.start, to: shot.end, in: snapshot) {
   176	            return "track \(angle) does not cover clip \(shot.id): nothing with a picture "
   177	                + "plays on it at tick \(tick)"
   178	        }
   179	        return nil
   180	    }
   181	
   182	    /// The held-trim sentence (SW-15 (e)).
   183	    private static func held(_ clip: UInt32, _ reached: Ticks, _ target: Ticks, shot: UInt32)
   184	        -> String
   185	    {
   186	        "clip \(clip)'s edge is held at tick \(reached), short of tick \(target), so clip "
   187	            + "\(shot) cannot be re-picked"
   188	    }
   189	
   190	    /// Each angle clip crossing `[from, to)` and the part of it a piece takes:
   191	    /// `[max(start, from), min(end, the next one's start, to))`, empty ones
   192	    /// skipped (SW-15 (d)).
   193	    static func pieceRanges(
   194	        angle: UInt32, from: Ticks, to: Ticks, in snapshot: ProjectSnapshot
   195	    ) -> [(clip: UInt32, from: Ticks, to: Ticks)] {
   196	        let crossing = pictureClips(on: angle, in: snapshot)
   197	            .filter { $0.end > from && $0.start < to }
   198	        var out: [(clip: UInt32, from: Ticks, to: Ticks)] = []
   199	        for (index, clip) in crossing.enumerated() {
   200	            let next = index + 1 < crossing.count ? crossing[index + 1].start : to
   201	            let low = max(clip.start, from)
   202	            let high = min(clip.end, next, to)
   203	            if high > low { out.append((clip.id, low, high)) }
   204	        }
   205	        return out
   206	    }
   207	
   208	    /// The handle the plan has reached and the ops that reached it.
   209	    struct Trial {
   210	        var project: ReelProject
   211	        var ops: [ReelOp] = []
   212	
   213	        /// Applies `op`; nil when it applied or changed nothing, else the
   214	        /// rule's sentence (nothing kept).
   215	        mutating func require(_ op: ReelOp) throws -> String? {
   216	            switch try project.applying(op) {
   217	            case .applied(let next):
   218	                project = next
   219	                ops.append(op)
   220	                return nil
   221	            case .identity:
   222	                ops.append(op)
   223	                return nil
   224	            case .refused(let refusal):
   225	                return refusal.reason
   226	            }
   227	        }
   228	
   229	        /// Keeps `op` only when it applied and the result `holds`.
   230	        mutating func attempt(_ op: ReelOp, holds: (ProjectSnapshot) -> Bool) throws -> Bool {
   231	            guard case .applied(let next) = try project.applying(op), holds(next.snapshot)
   232	            else { return false }
   233	            project = next
   234	            ops.append(op)
   235	            return true
   236	        }
   237	
   238	        /// The kind and style of `transition` on `clip`, when there was one.
   239	        mutating func putBack(_ transition: TransitionSnapshot?, on clip: UInt32) throws {
   240	            guard let transition else { return }
   241	            _ = try require(.setTransition(clip: clip, kind: transition.kind))
   242	            _ = try require(
   243	                .setTransitionStyle(
   244	                    clip: clip, curve: transition.curve, audio: transition.audio,
   245	                    audioShape: transition.audioShape))
   246	        }
   247	
   248	        /// A left-out edge's clip keeps no transition.
   249	        mutating func clearTransition(on clip: UInt32) throws {
   250	            guard project.snapshot.clip(clip)?.transitionIn != nil else { return }
   251	            _ = try require(.setTransition(clip: clip, kind: nil))
   252	        }
   253	    }
   254	}
     1	import AppKit
     2	
     3	/// Clip ▸ Switch Angle ▸ (road map "creator-jobs" SW1, spec §11 SW-13…SW-15):
     4	/// the one selected clip re-picked from the chosen covering track by
     5	/// `SwitchAngle.plan`, as one undo step through `applyEdit`, then the new
     6	/// pieces selected. A plan's refusal beeps and reaches the inspector's
     7	/// refusal strip. `switch_angle`'s tool mirrors it (`AgentServer+Switch.swift`).
     8	/// The rows are `SwitchAngleMenuFiller`'s (`AppDelegate+ClipMenus.swift`).
     9	extension EditorViewController {
    10	
    11	    /// The one selected clip when the menu may re-pick it: exactly one clip
    12	    /// selected, its track unlocked, no link (SW-15 (b)).
    13	    var switchAngleClip: ClipSnapshot? {
    14	        guard let document, selectedClips.count == 1, let clip = selectedClips.first,
    15	            clip.linked == nil,
    16	            document.editedProject.snapshot.track(clip.track)?.locked == false
    17	        else { return nil }
    18	        return clip
    19	    }
    20	
    21	    @objc func switchAngle(_ sender: Any?) {
    22	        guard let document, view.window?.attachedSheet == nil,
    23	            let track = ((sender as? NSMenuItem)?.representedObject as? NSNumber)?.uint32Value,
    24	            let clip = switchAngleClip
    25	        else {
    26	            NSSound.beep()
    27	            return
    28	        }
    29	        let answer: SwitchAngle.Answer
    30	        do {
    31	            answer = try SwitchAngle.plan(
    32	                clip: clip.id, angle: track, in: document.editedProject)
    33	        } catch {
    34	            NSSound.beep()
    35	            return
    36	        }
    37	        switch answer {
    38	        case .plan(let plan):
    39	            document.applyEdit(plan.actionName, plan.ops)
    40	            document.selection = Set(plan.pieces)
    41	        case .refused(let reason):
    42	            NSSound.beep()
    43	            NotificationCenter.default.post(
    44	                name: .projectDocumentDidRefuse, object: document,
    45	                userInfo: ["refusal": ReelRefusal(op: "switch_angle", reason: reason)])
    46	        }
    47	    }
    48	
    49	    /// The menu arm, answered from `validateUserInterfaceItem`'s default case;
    50	    /// nil for any other action. On when `switchAngleClip` exists, the item's
    51	    /// track is still one of its angles and no sheet is up; allowed inside a
    52	    /// nest.
    53	    func validateSwitchAngleAction(
    54	        _ action: Selector, item: any NSValidatedUserInterfaceItem
    55	    ) -> Bool? {
    56	        guard action == #selector(switchAngle(_:)) else { return nil }
    57	        guard let document, view.window?.attachedSheet == nil, let clip = switchAngleClip,
    58	            let track = ((item as? NSMenuItem)?.representedObject as? NSNumber)?.uint32Value
    59	        else { return false }
    60	        return SwitchAngle.angles(for: clip, in: document.editedProject.snapshot)
    61	            .contains { $0.track == track }
    62	    }
    63	}
     1	//! `copy_pieces` — a clip's pieces between given project times copied onto
     2	//! another track at the same times (road map "creator-jobs" SW1, spec §11
     3	//! SW-11, SW-12). It is the primitive Clip ▸ Switch Angle ▸ writes with: a
     4	//! piece of a synced angle shows the angle's own frame at every time.
     5	//!
     6	//! A piece is EXACTLY the middle a `split` at its two ends would leave —
     7	//! its source window, a ramp's map and rate, its actions clipped, a
     8	//! graphic's `in` and `length`, its words rebased — because it is made by
     9	//! `edit_split.rs`'s `split_clip` itself, on a scratch copy holding only the
    10	//! source clip. This module states none of those rules; it only says where
    11	//! the middle lands: a fresh id and fresh action ids from the result's own
    12	//! counter, `track` the destination, `start` the range's start, no
    13	//! transition and no link, and `enabled` overridden where `video`/`audio`
    14	//! are given.
    15	//!
    16	//! In order (SW-11): `Err` for an unknown clip, then for an unknown track;
    17	//! each pair put in order and snapped, a range empty on the grid dropped
    18	//! (nothing left is an identity), the rest sorted by start; then the
    19	//! refusals — a nest clip, a range outside the clip, overlapping ranges, a
    20	//! locked destination, a destination holding a clip over a range. The exit
    21	//! is `finish`.
    22	
    23	use crate::edit_clip::clip_end;
    24	use crate::edit_split::split_clip;
    25	use crate::edit_time::locked_track;
    26	use crate::model::{Clip, Project, Source};
    27	use crate::outcome::Outcome;
    28	use crate::time::Ticks;
    29	
    30	impl Project {
    31	    /// Copies `clip`'s pieces between each range's ends onto `track` at the
    32	    /// same project times (this module's doc, spec §6, §11 SW-11).
    33	    pub fn copy_pieces(
    34	        &self,
    35	        clip: u32,
    36	        track: u32,
    37	        ranges: &[[Ticks; 2]],
    38	        video: Option<bool>,
    39	        audio: Option<bool>,
    40	    ) -> Result<Outcome, String> {
    41	        let source = self.require_clip(clip)?.clone();
    42	        let destination = self.require_track(track)?;
    43	
    44	        let mut spans: Vec<(Ticks, Ticks)> = ranges
    45	            .iter()
    46	            .map(|[a, b]| {
    47	                let (low, high) = if a <= b { (*a, *b) } else { (*b, *a) };
    48	                (self.snapped(low), self.snapped(high))
    49	            })
    50	            .filter(|(from, to)| to > from)
    51	            .collect();
    52	        if spans.is_empty() {
    53	            return Ok(Outcome::Identity);
    54	        }
    55	        spans.sort_by_key(|&(from, to)| (from, to));
    56	
    57	        if let Some(why) = self.pieces_refusal(&source, destination.id, destination.locked, &spans)
    58	        {
    59	            return Ok(Outcome::Refused(why));
    60	        }
    61	
    62	        let mut scratch = self.clone();
    63	        scratch.clips = vec![source.clone()];
    64	        let mut next = self.clone();
    65	        let mut pieces: Vec<Clip> = Vec::with_capacity(spans.len());
    66	        for &(from, to) in &spans {
    67	            // `middle` answers `None` only when a cut is not strictly inside
    68	            // the clip, which the checks above rule out (every span is
    69	            // non-empty and inside the clip), so no range is ever skipped.
    70	            let Some(mut piece) = middle(&scratch, &source, from, to) else {
    71	                continue;
    72	            };
    73	            next.remint(&mut piece);
    74	            piece.track = track;
    75	            piece.start = from;
    76	            piece.transition_in = None;
    77	            piece.linked = None;
    78	            if let Some(on) = video {
    79	                piece.enabled.video = on;
    80	            }
    81	            if let Some(on) = audio {
    82	                piece.enabled.audio = on;
    83	            }
    84	            pieces.push(piece);
    85	        }
    86	        next.clips.extend(pieces);
    87	        self.finish(next)
    88	    }
    89	
    90	    /// The first refusal SW-11 names for `spans` (ordered, snapped, sorted),
    91	    /// in its order: a nest clip, a range outside the clip, overlapping
    92	    /// ranges, a locked destination, a destination holding a clip.
    93	    fn pieces_refusal(
    94	        &self,
    95	        source: &Clip,
    96	        track: u32,
    97	        locked: bool,
    98	        spans: &[(Ticks, Ticks)],
    99	    ) -> Option<String> {
   100	        if matches!(source.source, Source::Nest { .. }) {
   101	            return Some(format!(
   102	                "clip {} is a nest: a piece of it would replay the nest from its first frame",
   103	                source.id
   104	            ));
   105	        }
   106	        let (start, end) = (source.start, clip_end(source));
   107	        if let Some((from, to)) = spans.iter().find(|(from, to)| *from < start || *to > end) {
   108	            return Some(format!(
   109	                "range [{from}, {to}] is outside clip {}, which runs from {start} to {end}",
   110	                source.id
   111	            ));
   112	        }
   113	        if let Some(pair) = spans.windows(2).find(|pair| pair[0].1 > pair[1].0) {
   114	            let ((a, b), (c, d)) = (pair[0], pair[1]);
   115	            return Some(format!("ranges [{a}, {b}] and [{c}, {d}] overlap"));
   116	        }
   117	        if locked {
   118	            return Some(locked_track(track, "no piece can be copied onto it"));
   119	        }
   120	        let holder = self.clips_on_track(track).into_iter().find(|held| {
   121	            let held_end = clip_end(held);
   122	            spans
   123	                .iter()
   124	                .any(|(from, to)| held.start < *to && held_end > *from)
   125	        })?;
   126	        Some(format!(
   127	            "track {track} holds clip {} between {} and {}",
   128	            holder.id,
   129	            holder.start,
   130	            clip_end(holder)
   131	        ))
   132	    }
   133	}
   134	
   135	/// The middle `split_clip` leaves of `source` at `from` and `to` on a clone
   136	/// of `scratch` (the project holding only `source`): split at `from` when it
   137	/// is past the clip's start, the second half being the middle, then the
   138	/// middle split at `to` when it is before the clip's end, the first half
   139	/// being the middle (spec §11 SW-12).
   140	fn middle(scratch: &Project, source: &Clip, from: Ticks, to: Ticks) -> Option<Clip> {
   141	    let mut cut = scratch.clone();
   142	    let mut id = source.id;
   143	    if from > source.start {
   144	        if !split_clip(&mut cut, id, from) {
   145	            return None;
   146	        }
   147	        id = cut.clips.last()?.id;
   148	    }
   149	    if to < clip_end(source) && !split_clip(&mut cut, id, to) {
   150	        return None;
   151	    }
   152	    cut.clip(id).cloned()
   153	}
        }
        menu.addItem(.separator())
        for (index, row) in rows where row.kind != .corner {
            menu.addItem(tagged(row.title, action, index))
        }
        return menu
    }

    /// Clip ▸ Switch Angle ▸ (road map "creator-jobs" SW1, spec §11 SW-15
    /// (a)): the placeholder until it opens, when `SwitchAngleMenuFiller`
    /// writes one row per covering track of the one selected clip. No key
    /// equivalent.
    func switchAngleMenu() -> NSMenu {
        let menu = NSMenu(title: "Switch Angle")
        menu.delegate = SwitchAngleMenuFiller.shared
        menu.addItem(SwitchAngleMenuFiller.placeholder())
        return menu
    }

    /// One slot's kinds, the `transitionMenu()` idiom: the index as the tag,
    /// a separator, None as −1.
    private func motionSlotMenu(_ title: String, _ names: [String], _ action: Selector) -> NSMenu {
        let menu = NSMenu(title: title)
        for (index, name) in names.enumerated() {
            menu.addItem(tagged(name, action, index))
        }
        menu.addItem(.separator())
        menu.addItem(tagged("None", action, -1))
        return menu
    }

/// Clip ▸ Switch Angle ▸'s rows (spec §11 SW-15 (a)), rewritten each time the
/// menu opens for the main window's editor; `UIMenu.fillDynamic` asks it for
/// a named window. One row per `SwitchAngle.angles` of the ONE selected clip —
/// the track's title, its index as the tag, the track id as
/// `representedObject` — else the single `placeholder()`.
final class SwitchAngleMenuFiller: NSObject, NSMenuDelegate {
    static let shared = SwitchAngleMenuFiller()

    /// "No Covering Angle": `switchAngle(_:)` with no track, which its
    /// validator always turns off. It carries the action so the menu's
    /// selector is a live leaf before any project opens (the menu's
    /// three-way check, `v2_menu.py` H1).
    static func placeholder() -> NSMenuItem {
        NSMenuItem(
            title: "No Covering Angle",
            action: #selector(EditorViewController.switchAngle(_:)), keyEquivalent: "")
    }

    func menuNeedsUpdate(_ menu: NSMenu) {
        fill(menu, for: NSApp.mainWindow)
    }

    func fill(_ menu: NSMenu, for window: NSWindow?) {
        let editor = window?.contentViewController as? EditorViewController
        var angles: [SwitchAngle.Angle] = []
        if let editor, let document = editor.document, editor.selectedClips.count == 1,
            let clip = editor.selectedClips.first
        {
            angles = SwitchAngle.angles(for: clip, in: document.editedProject.snapshot)
        }
        menu.removeAllItems()
        guard !angles.isEmpty else {
            menu.addItem(Self.placeholder())
            return
        }
        for (index, angle) in angles.enumerated() {
            let item = NSMenuItem(
                title: angle.title,
                action: #selector(EditorViewController.switchAngle(_:)), keyEquivalent: "")
            item.tag = index
            item.representedObject = NSNumber(value: angle.track)
            menu.addItem(item)
        }
    }
