240	   240	                mic.covered[$0] && mic.voice[$0] >= input.settings.voiceThreshold
241	   241	            }
242	   242	            if !speaks {
243	   243	                out.append(
244	   244	                    "The microphone on track \(mic.track) has no speech between \(a) and \(b), "
