368	    68	            let frontIndex = snapshot.trackIndex(of: front),
369	    69	            let index = snapshot.trackIndex(of: track), index > frontIndex
370	    70	        else { return lead + "it is not in front of the angles." }
371	    71	        let over = clips.filter { $0.end > input.from && $0.start < input.to }
372	    72	        if over.isEmpty {
