388	    88	    /// SW-23's ops for `shots` (a `plan`'s, every shot's angle covering its span) over `input`'s
389	    89	    /// range, tried on `container`, the handle of the container being edited. `replacing` is
390	    90	    /// Replace's track, already through `replaceRefusal`. Throws only the core's invalid input.
391	    91	    static func edit(
392	    92	        _ shots: [Shot], input: Input, muteCameras: Bool, replacing: UInt32?,
393	    93	        selection: Set<UInt32>, in container: ReelProject
394	    94	    ) throws -> EditAnswer {
395	    95	        let snapshot = container.snapshot
396	    96	        let (from, to) = (input.from, input.to)
397	    97	        let angles = input.angles.map(\.track)
398	    98	        guard let front = angles.first, let frontIndex = snapshot.trackIndex(of: front) else {
399	    99	            return .refused(
400	   100	                "Switch by Speaker needs at least two angles: tracks holding a selected clip "
401	   101	                    + "with a picture.")
402	   102	        }
403	   103	
404	   104	        // (h): a linked angle clip crossing the range, before any op.
405	   105	        for track in angles {
406	   106	            for clip in SwitchAngle.pictureClips(on: track, in: snapshot)
407	   107	            where clip.end > from && clip.start < to {
408	   108	                if let partner = clip.linked {
409	   109	                    return .refused(
410	   110	                        "clip \(clip.id) on track \(track) is linked to clip \(partner) (Detach "
411	   111	                            + "Audio's pair); Switch by Speaker cuts between cameras with no link "
412	   112	                            + "— Attach Audio first")
413	   113	                }
414	   114	            }
415	   115	        }
416	   116	
417	   117	        var trial = SwitchAngle.Trial(project: container)
418	   118	        var chosen = selection
419	   119	        func refusal(_ op: ReelOp) throws -> String? {
420	   120	            try trial.require(op).map { "Switch by Speaker was refused at \(op.name): \($0)" }
421	   121	        }
422	   122	        /// Splits `clip` at `at`, a selected clip's new half joining the selection (f).
423	   123	        func split(_ clip: ClipSnapshot, at: Ticks) throws -> String? {
424	   124	            let known = Set(trial.project.snapshot.clips.map(\.id))
425	   125	            if let why = try refusal(.split(clips: [clip.id], at: at)) { return why }
426	   126	            if chosen.contains(clip.id) {
427	   127	                chosen.formUnion(trial.project.snapshot.clips.map(\.id).filter { !known.contains($0) })
