433	   133	        // (a) The destination.
434	   134	        let destination: UInt32
435	   135	        if let replacing {
436	   136	            for at in [from, to] {
437	   137	                for clip in trial.project.snapshot.clips(onTrack: replacing)
438	   138	                where clip.start < at && at < clip.end {
439	   139	                    if let why = try split(clip, at: at) { return .refused(why) }
440	   140	                }
441	   141	            }
442	   142	            let cleared = trial.project.snapshot.clips(onTrack: replacing).filter(inside).map(\.id)
