603	    88	    /// crosstalk runs, shorter than `bridge` in total, becomes crosstalk; the runs it joins merge.
604	    89	    static func bridgingCrosstalk(_ runs: [Run], under bridge: Ticks) -> [Run] {
605	    90	        var out: [Run] = []
606	    91	        var index = 0
607	    92	        while index < runs.count {
608	    93	            let run = runs[index]
609	    94	            if run.label != .crosstalk, var last = out.last, last.label == .crosstalk,
610	    95	                let next = runs[index...].firstIndex(where: { $0.label == .crosstalk }),
611	    96	                Ticks(runs[next].start - run.start) * stepTicks < bridge
612	    97	            {
