284	   284	    /// Wants every request under an owner of the call's own and waits (`waitForShots`' shape);
285	   285	    /// throws naming the first media not landed when one failed, the call was stopped, or the
286	   286	    /// bound passed (SW-86).
287	   287	    private func waitForFaces(
288	   288	        _ wants: [SpeakerSwitch.FacesWant], document: ProjectDocument, stop: AgentCallCancel?
289	   289	    ) throws {
290	   290	        let lane = AnalysisLane.shared
291	   291	        let requests = wants.map(\.request)
292	   292	        let owner = lane.newOwner()
293	   293	        defer { lane.release(owner: owner) }
294	   294	        lane.want(
295	   295	            requests, owner: owner,
296	   296	            alive: { document.isOpenForAnalysis && !(stop?.isCancelled ?? false) },
297	   297	            settled: { document.packageContentsDidChangeOnDisk() })
298	   298	        let outcome = lane.wait(
299	   299	            for: requests, owner: owner,
300	   300	            deadline: Date().addingTimeInterval(AnalysisLane.callWaitLimit),
301	   301	            cancelled: { stop?.isCancelled ?? false })
302	   302	        let open = wants.first { lane.run(of: $0.request)?.outcome != .landed } ?? wants[0]
303	   303	        let media = open.media.id
304	   304	        switch outcome {
305	   305	        case .landed: return
306	   306	        case .failed(let why):
307	   307	            throw ToolError(message: "The faces analysis of media \(media) failed: \(why).")
