267	   267	    /// How far `angle`'s clips cover contiguously from `t`; nil when they
268	   268	    /// do not cover `t` (SW-13's rule).
269	   269	    static func reach(_ angle: AngleTrack, from t: Ticks) -> Ticks? {
270	   270	        var reached = angle.clips.filter { $0.start <= t && $0.end > t }.map(\.end).max()
271	   271	        // A clip starting at or before the edge extends it (abutting files
272	   272	        // cover their join): loop until the edge no longer moves.
273	   273	        while let end = reached {
274	   274	            let further = angle.clips.filter { $0.start <= end && $0.end > end }.map(\.end).max()
275	   275	            guard let further else { break }
276	   276	            reached = further
277	   277	        }
278	   278	        return reached
279	   279	    }
