    39	/// The evaluated state as an action-style patch object, so `split` can hand
    40	/// the first half of a straddled action the state it must reach. A
    41	/// graphic's evaluated props go in as `graphic.props` (G-34), which
    42	/// [`narrow_to`] narrows to the props the action named, carrying its
    43	/// `kinds` through untouched.
    44	pub(crate) fn state_patch(evaluated: &Evaluated) -> Value {
    45	    let mut out = serde_json::Map::new();
    46	    // `video_json`: a tone key at exactly 0 at the cut must still be here,
    47	    // or `narrow_to` puts back the action's END value (spec §11 GR-2).
    48	    out.insert("video".to_string(), actions::video_json(&evaluated.video));
    49	    out.insert("audio".to_string(), actions::to_json(&evaluated.audio));
    50	    if let Some(text) = &evaluated.text {
    51	        out.insert("text".to_string(), actions::to_json(text));
    52	    }
    53	    if let Some(graphic) = &evaluated.graphic {
    54	        let mut props = serde_json::Map::new();
    55	        props.insert("props".to_string(), Value::Object(graphic.props.clone()));
    56	        out.insert("graphic".to_string(), Value::Object(props));
    57	    }
    58	    Value::Object(out)
    59	}
