    61	/// `state` narrowed to the keys `shape` mentions — the minimal patch with
    62	/// the same reach as the original. Keeping the shape means a split action's
    63	/// first half animates exactly the fields the whole action animated, rather
    64	/// than pinning every property of the clip.
    65	pub(crate) fn narrow_to(state: &Value, shape: &Value, depth: u32) -> Value {
    66	    let (Value::Object(from), Value::Object(keys)) = (state, shape) else {
    67	        return shape.clone();
    68	    };
    69	    if depth >= MAX_PATCH_DEPTH {
    70	        return shape.clone();
    71	    }
    72	    let mut out = serde_json::Map::new();
    73	    for (key, sub) in keys {
    74	        match from.get(key) {
    75	            Some(value) if value.is_object() && sub.is_object() => {
    76	                out.insert(key.clone(), narrow_to(value, sub, depth + 1));
    77	            }
    78	            Some(value) => {
    79	                out.insert(key.clone(), value.clone());
    80	            }
    81	            // A key the state does not have (an unknown patch key): carry
    82	            // the original through untouched, exactly as evaluation would.
    83	            None => {
    84	                out.insert(key.clone(), sub.clone());
    85	            }
    86	        }
    87	    }
    88	    Value::Object(out)
    89	}
