    91	/// Cuts `clip_id` in two at project time `at`, in place. Returns false —
    92	/// and changes nothing — when `at` is not strictly inside the clip, which
    93	/// is the spec's refusal.
    94	///
    95	/// The second clip's BASE props are the evaluated state at the cut, so the
    96	/// join is invisible; its actions are the ones that had not finished,
    97	/// rebased to its own clip time. A graphic's `props` are the evaluated
    98	/// ones, and a straddled action's first half ends at them (G-34).
    99	pub(crate) fn split_clip(project: &mut Project, clip_id: u32, at: Ticks) -> bool {
   100	    let Some(original) = project.clip(clip_id).cloned() else {
   101	        return false;
   102	    };
   103	    let clip_t = at.saturating_sub(original.start);
   104	    if clip_t <= 0 || clip_t >= original.duration {
   105	        return false;
   106	    }
   107	    let state = project.evaluate_clip(&original, clip_t);
   108	    let patch_source = state_patch(&state);
   109	    // The ORIGINAL's map, read once: a ramped clip's halves meet at the
   110	    // source it read by the cut (spec §11 SR-18 (e)). `None` for a
   111	    // constant clip, which takes the one-rate path unchanged.
   112	    let map = SpeedMap::of(&original);
   113	    // Measured on the ORIGINAL, so a null `length` is `in` plus the WHOLE
   114	    // duration, not the half either piece keeps.
   115	    let pinned = effective_length(&original);
   116	
   117	    let mut second = original.clone();
   118	    second.id = project.allocate_id();
   119	    second.start = at;
   120	    second.duration = clip_end(&original).saturating_sub(at);
   121	    // The cut consumes `clip_t` of timeline, which is `clip_t * speed` of
   122	    // source — round(S(cut)) on a ramped clip, whose second half starts at
   123	    // the rate in force there; a still's frozen frame and the sourceless
   124	    // kinds do not move, which is `source_advanced_through`'s own rule.
   125	    second.source = source_advanced_through(&original, clip_t);
   126	    if let Some(map) = &map {
   127	        second.speed = map.rate_at(clip_t);
   128	    }
   129	    // A graphic's own timeline (road map 10's G-9): the second half starts
   130	    // `clip_t` further into it, and BOTH halves keep the original's length,
   131	    // so the join is invisible and neither half's outro moves — the first
   132	    // half's `in + duration` would otherwise be only the head.
   133	    second.graphic = graphic_advanced(state.graphic.as_ref(), clip_t);
   134	    if let Some(graphic) = second.graphic.as_mut() {
   135	        graphic.length = pinned;
   136	    }
   137	    // Presence of a group is a fact about the clip, so an audio-only clip
   138	    // stays audio-only; only the values come from the evaluation.
   139	    // The cursor's `smoothing` and `hide_idle` stay the original's BASE
   140	    // values, never an end's (spec §11 CU-30).

