     3	/// Switch by Speaker's one reader (spec §11 SW-20, SW-25), shaped like
     4	/// `AudioSync.read`: the edited project's snapshot and plan, and each
     5	/// microphone's loudness and speech caches, read onto the range's 10 ms grid
     6	/// through `ClipLevelSeries`. A missing cache file is "still being analysed",
     7	/// never silence. In the faces mode (SW8) it also reads each face speaker's
     8	/// angle through `readFaces` (`SpeakerSwitch+Faces.swift`).
     9	extension SpeakerSwitch {
    10	    /// `clips` nil: the document's selection. `pairing` nil: SW-20's
    11	    /// defaults. `range` nil: the In–Out range, else the selected angle
    12	    /// clips' extent. nil only when the edited project's plan cannot be read.
    13	    static func read(
    14	        from document: ProjectDocument, clips: [UInt32]?, pairing: Pairing?,
    15	        range: (from: Ticks, to: Ticks)?, settings: Settings
    16	    ) -> Input? {
    17	        let project = document.editedProject
    18	        guard let plan = project.plan else { return nil }
    19	        let snapshot = project.snapshot
    20	        var seen: Set<UInt32> = []
    21	        let selection = (clips ?? document.selection.sorted())
    22	            .filter { seen.insert($0).inserted }
    23	            .compactMap { snapshot.clip($0) }
    24	        let implied = defaults(selection: selection, in: snapshot)
    25	        let pairing = pairing ?? implied.pairing
    26	
    27	        // A named pairing's microphones are the tracks it names that hold a
    28	        // selected sounding clip, a detached camera sound included (SW-20).
    29	        let front = snapshot.tracks.reversed().map(\.id)
    30	        let microphoneTracks: [UInt32]
    31	        if pairing == implied.pairing {
    32	            microphoneTracks = implied.microphones
    33	        } else {
    34	            let named = Set(pairing.speakers.compactMap(\.mic))
    35	            microphoneTracks = front.filter { track in
    36	                named.contains(track) && selection.contains {
    37	                    guard $0.track == track, case .media = $0.source, $0.enabled.audio else {
    38	                        return false
    39	                    }
    40	                    return snapshot.media(for: $0)?.hasAudio == true
    41	                }
    42	            }
    43	        }
    44	
    45	        let angles = implied.angles.map { track in
    46	            AngleTrack(
    47	                track: track,
    48	                clips: SwitchAngle.pictureClips(on: track, in: snapshot).map {
    49	                    Span(clip: $0.id, start: $0.start, end: $0.end)
    50	                })
    51	        }
    52	        let angleClips = selection.filter {
    53	            implied.angles.contains($0.track) && isPicture($0, in: snapshot)
    54	        }
    55	        let span = range ?? document.inOutRange.map { ($0.start, $0.end) }
    56	            ?? (angleClips.map(\.start).min() ?? 0, angleClips.map(\.end).max() ?? 0)
    57	        let step = stepTicks
    58	        let count = step > 0 ? Int(max(0, span.1 - span.0) / step) : 0
    59	
    60	        let segments = AudioNormalize.audioSegments(in: plan)
    61	        let voiced = SileroVAD.isAvailable
    62	        var loudness: [UInt32: MediaLoudness] = [:]
    63	        var speech: [UInt32: [Float]] = [:]
    64	        var problems: [String] = []
    65	        var microphones: [Microphone] = []
    66	        for track in microphoneTracks {
    67	            let clips = selection.filter { $0.track == track && segments[$0.id] != nil }
    68	                .sorted { $0.start < $1.start }
    69	            let media = clips.compactMap { segments[$0.id]?.first?.media }
    70	            for id in media where loudness[id] == nil {
    71	                if let read = document.cacheDirectory.flatMap({
    72	                    MediaImporter.loadLoudness(for: id, in: $0)
    73	                }) { loudness[id] = read }
    74	            }
    75	            if voiced {
    76	                for id in media where speech[id] == nil {
    77	                    if let read = document.cacheDirectory.flatMap({
    78	                        MediaImporter.loadSpeech(for: id, in: $0)
    79	                    }) { speech[id] = read }
    80	                }
    81	            }
    82	            let unread = "The microphone on track \(track) is still being analysed — its "
    83	            var pending = false
    84	            if media.contains(where: { loudness[$0] == nil }) {
    85	                pending = true
    86	                problems.append(unread + "loudness has not been measured yet. Try again in a moment.")
    87	            } else if voiced, media.contains(where: { speech[$0] == nil }) {
    88	                pending = true
    89	                problems.append(unread + "speech has not been detected yet. Try again in a moment.")
    90	            }
    91	            guard !pending, voiced else {
    92	                microphones.append(Microphone(track: track, level: [], voice: [], covered: []))
    93	                continue
    94	            }
    95	            var energy = [Double](repeating: 0, count: count)
    96	            var voice = [Float](repeating: 0, count: count)
    97	            var covered = [Bool](repeating: false, count: count)
    98	            for clip in clips {
    99	                guard let own = segments[clip.id], let first = own.first,
   100	                    let cache = loudness[first.media]
   101	                else { continue }
   102	                let cited = own.filter { $0.media == first.media }
   103	                let pivots = cited.map { MediaPeaks.reversedPivot(for: $0, in: snapshot) }
   104	                let low = cited.map(\.start).min() ?? 0
   105	                let high = cited.map { $0.start + $0.duration }.max() ?? 0
   106	                let k0 = max(0, Int(MediaPeaks.bucketIndex(low - span.0, bucket: step)))
   107	                let k1 = min(count, Int(MediaPeaks.bucketIndex(high - span.0 + step - 1, bucket: step)))
   108	                guard k1 > k0 else { continue }
   109	                let origin = span.0 + Ticks(k0) * step
   110	                let read = ClipLevelSeries.energies(
   111	                    cache, segments: cited, pivots: pivots, matrix: .init(clip.audio),
   112	                    from: origin, count: k1 - k0)
   113	                let p = ClipLevelSeries.voice(
   114	                    speech[first.media] ?? [], segments: cited, pivots: pivots, from: origin,
   115	                    count: k1 - k0)
   116	                for j in 0..<(k1 - k0) where read.covered[j] {
   117	                    energy[k0 + j] = read.energy[j]
   118	                    voice[k0 + j] = p[j]
   119	                    covered[k0 + j] = true
   120	                }
   121	            }
   122	            microphones.append(
   123	                Microphone(
   124	                    track: track, level: ClipLevelSeries.levels(energy), voice: voice,
   125	                    covered: covered))
   126	        }
   127	        if !voiced {
   128	            problems.append(
   129	                "Speech detection is unavailable on this Mac, so Switch by Speaker cannot tell "
   130	                    + "who is talking.")
   131	        }
   132	        // SW-84: the faces mode's angles, their problems after the microphones'.
   133	        var faces: [FaceAngle] = []
   134	        if mode(pairing) == .faces {
   135	            let read = readFaces(
   136	                from: document, angles: angles, pairing: pairing, from: span.0, count: count)
   137	            faces = read.faces
   138	            problems += read.problems
   139	        }
   140	        return Input(
   141	            from: span.0, to: span.1, fps: snapshot.canvas.fps, angles: angles,
   142	            microphones: microphones, pairing: pairing, problems: problems,
   143	            clipCount: ShotSplit.clipCount(document.project.snapshot), settings: settings,
   144	            faces: faces)
   145	    }
   146	}
