    13	
    14	    // MARK: - The mode (SW-83)
    15	
    16	    /// Each speaker whose angle is the wide AND whose microphone another speaker shares is
    17	    /// dropped; every other pairing comes back identical.
    18	    static func withoutWide(_ pairing: Pairing) -> Pairing {
    19	        guard let wide = pairing.wide else { return pairing }
    20	        let speakers = pairing.speakers
    21	        let kept = speakers.indices.filter { i in
    22	            guard speakers[i].angle == wide, let mic = speakers[i].mic else { return true }
    23	            return !speakers.indices.contains { $0 != i && speakers[$0].mic == mic }
    24	        }
    25	        return Pairing(speakers: kept.map { speakers[$0] }, wide: wide)
    26	    }
    27	
    28	    /// The speakers with an angle that is not the wide, the first per angle.
    29	    static func faceSpeakers(_ pairing: Pairing) -> [Speaker] {
    30	        var seen: Set<UInt32> = []
    31	        return pairing.speakers.filter { speaker in
    32	            guard let angle = speaker.angle, angle != pairing.wide else { return false }
    33	            return seen.insert(angle).inserted
    34	        }
    35	    }
    36	
    37	    /// Faces when two or more face speakers all name one microphone; else microphones.
    38	    static func mode(_ pairing: Pairing) -> Mode {
    39	        let speakers = faceSpeakers(pairing)
    40	        guard speakers.count >= 2, let mic = speakers[0].mic,
    41	            speakers.allSatisfy({ $0.mic == mic })
    42	        else { return .microphones }
    43	        return .faces
    44	    }
