    54	    // MARK: - The labels (SW-81)
    55	
    56	    /// One label per step: `.person(angle track)`, `.crosstalk` or `.nobody`. A step is speech
    57	    /// when the shared microphone covers it at v ≥ `voice_threshold`; the face speakers' angles
    58	    /// contest it front first.
    59	    static func faceLabels(_ input: Input) -> [Label] {
    60	        let step = stepTicks
    61	        let count = step > 0 ? Int(max(0, input.to - input.from) / step) : 0
    62	        let nobody = [Label](repeating: .nobody, count: count)
